<script setup>
import { ref,onMounted,onBeforeUnmount,watch } from 'vue'
import EventPicker from './EventPicker.vue'
import { api } from '../api'
import { localDate,storageKey,accountEpoch } from '../session'
import { useWorkflowWrite } from '../composables/useWorkflowWrite'
const emit=defineEmits(['saved'])
const props=defineProps({todayOnly:Boolean}),day=ref(localDate()),schedules=ref([]),rows=ref([]),history=ref([]),drafts=ref({}),goals=ref([]),error=ref(''),notice=ref('')
const emptyForm=()=>({name:'',frequency:'daily',start:day.value,weekdays:[],interval:1,enabled:true,goal_id:null,planned_minutes:30})
const form=ref(emptyForm()),editing=ref(null),writes=useWorkflowWrite('plans'),epoch=accountEpoch,key=storageKey('plan-drafts-v2')
let request=0,alive=true
try{drafts.value=JSON.parse(localStorage.getItem(key)||'{}')}catch{}
const draftKey=item=>(item.local_date||day.value)+':'+item.schedule.id
const fresh=()=>({outcome:'done',content:'',actual:null,unit:'',event_id:null,event_version:null,selected:null,correction:false,reason:'',ai_permission:'private'})
watch(drafts,value=>{if(epoch===accountEpoch){try{localStorage.setItem(key,JSON.stringify(value))}catch{error.value='本机草稿空间不足；当前输入仍保留，请保存到服务端。'}}},{deep:true,flush:'sync'})
async function load(){const token=++request,selectedDay=day.value;rows.value=[];try{const [all,today,past,goalRows]=await Promise.all([api.flow('/plan-schedules'),api.flow(props.todayOnly?'/plan-occurrences?today=true':'/plan-occurrences?day='+selectedDay),api.flow('/plan-occurrences'),api.flow('/goals')]);if(!alive||epoch!==accountEpoch||request!==token||selectedDay!==day.value)return;schedules.value=all;rows.value=today.items;history.value=past.history;goals.value=goalRows;for(const item of rows.value){const k=draftKey(item);if(!drafts.value[k]){let legacy={};try{legacy=JSON.parse(localStorage.getItem(storageKey('plan-drafts:'+(item.local_date||selectedDay)))||'{}')[item.schedule.id]||{}}catch{};drafts.value[k]={...fresh(),...legacy}}}}catch(e){if(token===request)error.value=e.message}}
async function act(fn){if(writes.busy.value)return;error.value='';notice.value='';try{await fn()}catch(e){error.value=e.message}}
async function save(){await act(async()=>{await writes.send('/plan-schedules'+(editing.value?'/'+editing.value.id:''),{...form.value,expected_version:editing.value?.version||0},editing.value?'PUT':'POST');form.value=emptyForm();editing.value=null;await load();notice.value='日程已保存。'})}
async function result(item){await act(async()=>{const k=draftKey(item),{selected,...input}=drafts.value[k];const saved=await writes.send(`/plan-schedules/${item.schedule.id}/occurrences/${item.local_date||day.value}`,{...input,actual:input.actual===''?null:input.actual,event_id:selected?.id||null,event_version:selected?.content_version||null,schedule_version:item.schedule.version,expected_version:item.occurrence?.version||0},'PUT');if(saved.event_id)emit('saved');if(saved.event_id&&input.ai_permission==='allowed'&&!selected){try{const event=await api.getEvent(saved.event_id);await api.submitJob(event.id,{request_key:crypto.randomUUID(),event_version:event.content_version,operation:'facts'})}catch(e){error.value='实际事实已保存；'+e.message}}delete drafts.value[k];try{const legacyKey=storageKey('plan-drafts:'+(item.local_date||day.value)),legacy=JSON.parse(localStorage.getItem(legacyKey)||'{}');delete legacy[item.schedule.id];localStorage.setItem(legacyKey,JSON.stringify(legacy))}catch{};await load();if(input.outcome==='missed')notice.value='';else notice.value='实际事实已保存；分析后再主动确认入账。'})}
async function recover(){await act(async()=>{const pending=writes.pending.value;if(!pending)return;const m=pending.path.match(/plan-schedules\/(\d+)\/occurrences\/(.+)$/);await writes.send(pending.path,pending.body,pending.method);if(m)delete drafts.value[m[2]+':'+m[1]];await load();notice.value='上次请求已恢复。'})}
function edit(row){editing.value=row;form.value={name:row.name,...row.rule,start:localDate(),enabled:row.enabled,goal_id:row.goal_id,planned_minutes:row.rule.planned_minutes??30};delete form.value.timezone}
watch(day,load);onMounted(load);onBeforeUnmount(()=>{alive=false;request++})
</script>
<template><section class="card plan-agenda"><RouterLink class="btn" to="/timers">计划 / 娱乐计时 →</RouterLink><h2>{{ todayOnly?'今天到期的计划':'计划日程' }}</h2><p v-if="error" class="error" role="alert">{{ error }}</p><p v-if="notice" role="status">{{ notice }}</p><p v-if="writes.pending.value">上次结果未知。<button class="btn" :disabled="writes.busy.value" @click="recover">恢复上次请求</button></p>
<template v-if="!todayOnly"><details><summary>{{ editing?'编辑日程':'创建日程' }}</summary><form @submit.prevent="save"><label>计划名称<input v-model="form.name" maxlength="120" required/></label><label>{{ editing?'修改生效日期':'开始日期' }}<input type="date" v-model="form.start" required/></label><label>周期<select v-model="form.frequency"><option value="daily">每天</option><option value="workdays">工作日</option><option value="weekends">周末</option><option value="once">指定日期单次</option><option value="manual">自行安排</option><option value="weekdays">指定星期</option><option value="interval">间隔日</option></select></label><div v-if="form.frequency==='weekdays'" class="action-group"><label v-for="(name,i) in ['一','二','三','四','五','六','日']" :key="i"><input type="checkbox" :value="i" v-model="form.weekdays"/>周{{ name }}</label></div><label v-if="form.frequency==='interval'">间隔天数<input type="number" min="1" max="366" v-model.number="form.interval"/></label><label>预计分钟数<input type="number" min="1" max="1440" v-model.number="form.planned_minutes" required/></label><label>关联目标<select v-model="form.goal_id"><option :value="null">不关联</option><option v-for="goal in goals.filter(g=>g.status==='active')" :value="goal.id" :key="goal.id">{{ goal.description }}</option></select></label><label><input type="checkbox" v-model="form.enabled"/>启用</label><button class="btn primary" :disabled="writes.busy.value||!!writes.pending.value">保存日程</button></form></details><details><summary>全部日程 · {{ schedules.length }}</summary><article v-for="row in schedules" :key="row.id"><b>{{ row.name }}</b> · {{ {daily:'每天',workdays:'工作日',weekends:'周末',once:'指定日期',manual:'自行安排',weekdays:'指定星期',interval:'间隔日'}[row.rule.frequency] }} · {{ row.enabled?'启用':'已停用' }}<button class="btn" @click="edit(row)">编辑周期 / 停用</button><details><summary>周期历史</summary><p v-for="rev in row.history" :key="rev.version">v{{ rev.version }} · {{ rev.rule.start }} 生效 · {{ {daily:'每天',workdays:'工作日',weekends:'周末',once:'指定日期',manual:'自行安排',weekdays:'指定星期',interval:'间隔日'}[rev.rule.frequency] }}</p></details></article></details><label>查看安排日期<input type="date" v-model="day"/></label></template>
<p v-if="!rows.length" class="muted">这一天没有到期安排。总表保留其他计划，未操作不算未完成。</p>
<article v-for="item in rows" :key="item.schedule.id" class="plan-card"><h3>{{ item.schedule.name }}</h3><p class="muted">{{ item.local_date||day }} · {{ item.schedule.rule.timezone }} · 预计 {{ item.schedule_snapshot?.rule.planned_minutes??item.schedule.rule.planned_minutes??30 }} 分钟</p><p v-if="item.occurrence">{{ {done:'完成',partial:'部分完成',missed:'未完成'}[item.occurrence.outcome] }} · 已锁定 v{{ item.occurrence.version }}</p><template v-if="drafts[draftKey(item)]"><template v-if="!item.occurrence||drafts[draftKey(item)].correction"><label>实际结果<select v-model="drafts[draftKey(item)].outcome"><option value="done">完成</option><option value="partial">部分完成</option><option value="missed">未完成</option></select></label><template v-if="drafts[draftKey(item)].outcome!=='missed'"><label>实际事实<textarea v-model="drafts[draftKey(item)].content" rows="3"/></label><div class="form-grid"><label>实际量（可空，不默认比例）<input type="number" min="0" step="any" v-model.number="drafts[draftKey(item)].actual"/></label><label>单位<input v-model="drafts[draftKey(item)].unit" maxlength="40"/></label></div><label v-if="!drafts[draftKey(item)].selected">保存方式<select v-model="drafts[draftKey(item)].ai_permission"><option value="private">只保存，不交给 AI</option><option value="allowed">保存并分析</option></select></label><details><summary>关联已保存事件，避免重复记录</summary><EventPicker v-model="drafts[draftKey(item)].selected" :day="item.local_date||day"/></details></template><label v-if="drafts[draftKey(item)].correction">纠错原因<textarea v-model="drafts[draftKey(item)].reason"/></label><button class="btn" :disabled="writes.busy.value||!!writes.pending.value" @click="result(item)">{{ drafts[draftKey(item)].outcome==='missed'?'确认未完成并锁定':'保存实际事实' }}</button></template><button v-else class="btn" @click="drafts[draftKey(item)].correction=true">显式纠错</button></template><RouterLink v-if="item.occurrence?.event_id" :to="'/events/'+item.occurrence.event_id">查看事实、分析与入账 →</RouterLink></article>
<details v-if="!todayOnly"><summary>当次历史</summary><article v-for="row in history" :key="row.id"><b>{{ row.local_date }} · {{ row.schedule_snapshot.name }}</b><p>{{ {done:'完成',partial:'部分完成',missed:'未完成'}[row.outcome] }} · 实际量 {{ row.facts.actual??'未填' }} {{ row.facts.unit }}</p><details><summary>更正记录</summary><p v-for="rev in row.history" :key="rev.version">v{{ rev.version }} · {{ {done:'完成',partial:'部分完成',missed:'未完成'}[rev.outcome] }} · {{ rev.facts.correction_reason }}{{ rev.prior_booking_retained?' · 原结算保留':'' }}</p></details></article></details></section></template>
